// Solid Ten Sign: verify the webhook signature, refuse replays, keep only completed documents.
const crypto = require('crypto');

const SECRET = 'REPLACE_WITH_YOUR_WEBHOOK_SECRET';
const TOLERANCE_SECONDS = 300;

const results = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const timestamp = String(headers['x-solidten-timestamp'] || '');
  const signature = String(headers['x-solidten-signature'] || '');

  // n8n parsed the JSON body. Solid Ten Sign sends JSON.stringify output, so stringifying the
  // parsed body again gives back the exact bytes that were signed.
  const rawBody = JSON.stringify(item.json.body);

  if (!/^\d+$/.test(timestamp) || !/^v1=[0-9a-f]{64}$/.test(signature)) {
    throw new Error('Missing or malformed signature headers');
  }

  if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > TOLERANCE_SECONDS) {
    throw new Error('Delivery is too old (possible replay)');
  }

  const expected = 'v1=' + crypto.createHmac('sha256', SECRET).update(timestamp + '.' + rawBody, 'utf8').digest('hex');

  if (expected.length !== signature.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))) {
    throw new Error('Signature does not match');
  }

  if (item.json.body.event !== 'DOCUMENT_COMPLETED') {
    continue;
  }

  results.push({ json: { event: item.json.body.event, document: item.json.body.payload } });
}

return results;
